const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const clean = s => String(s ?? '').replace(/[\u0000-\u001f\u007f]/g,'·');
const defangIp = ip => String(ip ?? '').replace(/\./g,'[.]');
const defangUrl = u => clean(u).replace(/^http/i,'hxxp').replace(/\./g,'[.]');
const nolink = s => clean(s).replace(/:\/\//g,'[://]');
const n = x => Number(x ?? 0).toLocaleString('en-US');
const j = $input.first().json, e = j.execution ?? {};
const msg = clean(e.error?.message ?? 'unknown error').slice(0, 300);
const text = `⚠️ <b>n8n workflow failed</b>\n<b>Workflow</b>: ${esc(j.workflow?.name)}\n<b>Node</b>: ${esc(e.lastNodeExecuted ?? '-')}\n<b>Error</b>: <code>${esc(msg)}</code>\n<b>When</b>: ${new Date().toISOString().slice(0,16).replace('T',' ')} UTC (execution ${esc(e.id ?? '-')})`;
return [{ json: { text } }];
